import json
Q=[]
def q(n,ru,kk,ropts,kopts=None,**kw):
    d={'n':n,'ru':{'q':ru,'opts':ropts},'kk':{'q':kk,'opts':kopts if kopts is not None else ropts}}; d.update(kw); Q.append(d)
q(1,"Алуа прошла в первый день 16% пути. Во второй день 2/7 часть от остатка, а в третий день 50% от остатка, и Дарья сказала ей, что еще осталось 60 км. Сколько всего должна была пройти Алуа за три дня?","Алуа бірінші күні жолдың 16%-ын жүрді. Екінші күні қалғанының 2/7 бөлігін, ал үшінші күні қалғанының 50%-ын жүрді, сонда Дарья оған тағы 60 км қалғанын айтты. Алуа үш күнде барлығы қанша жол жүруі керек еді?",["400","500","200","300"])
q(2,"Машина ехала 4 ч со скоростью 90 км/ч, потом 1 ч – со скоростью 60 км/ч, а еще 3 ч – со скоростью 120 км/ч. С какой постоянной скоростью должен ехать автобус, чтобы пройти весь путь за это же время?","Көлік 4 сағат 90 км/сағ жылдамдықпен, содан кейін 1 сағат 60 км/сағ жылдамдықпен, тағы 3 сағат 120 км/сағ жылдамдықпен жүрді. Автобус бүкіл жолды сол уақытта жүріп өту үшін қандай тұрақты жылдамдықпен жүруі керек?",["96,5","95,5","97,5","98"])
q(3,"Весь путь поделен на равные части. В первый день путешественники преодолели пять частей пути, во второй семь, а в третий день еще три части пути. Какое расстояние преодолели путешественники в третий день, если весь путь составлял 735 км?","Бүкіл жол тең бөліктерге бөлінген. Бірінші күні саяхатшылар жолдың бес бөлігін, екінші күні жетіні, ал үшінші күні тағы үш бөлігін жүріп өтті. Бүкіл жол 735 км болса, үшінші күні саяхатшылар қанша қашықтық жүрді?",["343","245","147","490"])
q(4,"Расстояние между городами 666 км. Из них одновременно в противоположных направлениях вышли 2 поезда. Какое расстояние будет между поездами через 2 ч, если скорость первого – 78 км/ч, а второго – на 9 км/ч больше?","Қалалар арасындағы қашықтық 666 км. Олардан бір мезгілде қарама-қарсы бағытта 2 пойыз шықты. Біріншісінің жылдамдығы 78 км/сағ, ал екіншісінікі 9 км/сағ артық болса, 2 сағаттан кейін пойыздар арасындағы қашықтық қандай болады?",["436","330","336","430"])
q(5,"На участке дороги бетонные плиты длиной 6 м заменили новыми длиной 12 м. Сколько нужно старых плит для замены 10 новых?","Жол учаскесінде ұзындығы 6 м бетон плиталарды ұзындығы 12 м жаңаларымен ауыстырды. 10 жаңа плитаны ауыстыру үшін неше ескі плита қажет?",["5","15","20","10"])
q(6,"С помощью координатной прямой определите сумму чисел N, F, K и M.","Координаталық түзудің көмегімен N, F, K және M сандарының қосындысын анықтаңыз.",["7","9","12","17"],figMid=['nl5'])
q(7,"Из города выехал автобус. После того как он проехал 234 км за 3 ч, из того же города в том же направлении выехал мотоциклист и догнал автобус через 2 часа. Найдите скорость мотоциклиста.","Қаладан автобус шықты. Ол 3 сағатта 234 км жүріп өткен соң, сол қаладан сол бағытта мотоциклші шығып, автобусты 2 сағаттан кейін қуып жетті. Мотоциклшінің жылдамдығын табыңыз.",["185","165","175","195"])
q(8,"Теплоход прошел по течению реки 48 км за 3 ч. Сколько времени понадобится на обратный путь, если скорость течения реки равна 2000 м/ч?","Теплоход өзен ағысымен 48 км жолды 3 сағатта жүріп өтті. Өзен ағысының жылдамдығы 2000 м/сағ болса, кері жолға қанша уақыт қажет?",["3,8 ч","3,4 ч","3,6 ч","4 ч"],["3,8 сағ","3,4 сағ","3,6 сағ","4 сағ"])
q(9,"Концентрация соли в растворе равна 24%. Сколько грамм соли содержится в 150 г такого раствора?","Ерітіндідегі тұздың концентрациясы 24%. Осындай 150 г ерітіндіде неше грамм тұз бар?",["36","114","46","56"])
q(10,r"Длина первой окружности 25,12 дм. Диаметр второй окружности в 2 раза больше диаметра первой окружности. Найдите площадь второй окружности.",r"Бірінші шеңбердің ұзындығы 25,12 дм. Екінші шеңбердің диаметрі бірінші шеңбердің диаметрінен 2 есе үлкен. Екінші шеңбердің ауданын табыңыз.",[r"\(36\pi\)",r"\(49\pi\)",r"\(64\pi\)",r"\(50{,}24\pi\)"])
q(11,r"Упростите: \(5(4x+y)-2(x-y)\).",r"Ықшамдаңыз: \(5(4x+y)-2(x-y)\).",[r"\(18x+2y\)",r"\(18x+3y\)",r"\(18x+4y\)",r"\(18x+7y\)"])
q(12,"Первое число составляет 80% от второго. Тогда второе число от первого составляет:","Бірінші сан екіншісінің 80%-ын құрайды. Онда екінші сан бірінші санның қанша пайызын құрайды:",["120%","150%","100%","125%"])
q(13,r"Угол \(340^\circ\) разделили на три части в отношении 1,1 : 1,4 : 0,9. Найдите градус половины меньшего угла.",r"\(340^\circ\) бұрышын 1,1 : 1,4 : 0,9 қатынасындай үш бөлікке бөлді. Ең кіші бұрыштың жартысының градусын табыңыз.",[r"\(90^\circ\)",r"\(70^\circ\)",r"\(55^\circ\)",r"\(45^\circ\)"])
q(14,"В магазине электроники проходит акция. Артур купил в этом магазине планшет за 240 000 тенге. Какова была цена планшета без скидки?","Электроника дүкенінде акция өтіп жатыр. Артур осы дүкенде планшетті 240 000 теңгеге сатып алды. Планшеттің жеңілдіксіз бағасы қандай болған?",["260 000 тг","288 000 тг","300 000 тг","312 000 тг"],["260 000 тг","288 000 тг","300 000 тг","312 000 тг"],figMid=['sale5_@'])
